parameters.jsCode:
return $input.all().map(item => {
  const data = item.json;

  // Limpa e padroniza o telefone
  const telefoneLimpo = data.phoneUnformatted || data.phone || "";

  // Monta o link do Google Meu Negócio
  const linkGMB = data.url || (data.placeId ? `https://www.google.com/maps/place/?q=place_id:${data.placeId}` : "");

  return {
    json: {
      whatsapp: telefoneLimpo,
      nome_negocio: data.title || "",
      nome_contato: "", 
      link_gmb: linkGMB,
      endereco: data.address || "",
      bairro: data.neighborhood || "",
      segmento: data.categoryName || "",
      site: data.website || "",
      instagram: data.instagram || "",
      email: data.email || "",
      nota_google: data.totalScore || 0,
      qntd_avaliacoes: data.reviewsCount || 0,
      comercio_fechou: data.permanentlyClosed || false,
      distribuicao_reviews: data.reviewsDistribution || null,
      tag_origem: "Google Maps",
      status: "pendente"
    }
  };
});

// 1. Pega os dados que saíram da raspagem (do nó Padronizar Dados)
const leads = $('Padronizar Dados').all().map(item => item.json);

// 2. Pega a lista de números de WhatsApp que o Supabase retornou
const whatsappsExistentes = $input.all().map(item => item.json.whatsapp).filter(Boolean);

// 3. Aplica o filtro em todos os leads simultaneamente
const leadsLimpos = leads.filter(lead => {
  const whatsappLead = lead.whatsapp || lead.telefone || lead.phone || '';
  const status = lead.status || lead.businessStatus || '';

  // Regras de bloqueio
  const isDuplicado = whatsappsExistentes.includes(whatsappLead);
  const isFechado = status.toUpperCase().includes('CLOSED');

  // O lead só passa se NÃO for duplicado e NÃO estiver fechado
  return !isDuplicado && !isFechado;
});

// 4. Se todo mundo for descartado, encerra aqui. Se tiver lead bom, manda para frente.
if (leadsLimpos.length === 0) {
  return []; 
}

return leadsLimpos.map(lead => ({ json: lead }));
